# Same scan for purified <|im_end|> direction (thoroughness)
import numpy as np, torch, json
from collections import Counter
recs = [json.loads(l) for l in open('/practice/baseline/original.jsonl')]
cnt = Counter()
for r_ in recs: cnt.update(tok.encode(r_['text']).ids)
freq = [t for t,_ in cnt.most_common(60) if t not in (248069, 248046)][:40]
E = load_original('model.language_model.embed_tokens.weight'); gn = load_original('model.language_model.norm.weight')
def rt(t): return (E[t]*(1+gn)).numpy().astype(np.float64)
F = np.stack([rt(t) for t in freq], axis=1)
def pure(t):
    rr = rt(t)
    return rr - F @ np.linalg.solve(F.T@F, F.T@rr)
d2 = pure(248046); d2 /= np.linalg.norm(d2)
writers = ([f'model.language_model.layers.{L}.mlp.down_proj.weight' for L in range(24)] +
           [f'model.language_model.layers.{L}.self_attn.o_proj.weight' for L in [3,7,11,15,19,23]] +
           [f'model.language_model.layers.{L}.linear_attn.out_proj.weight' for L in range(24) if L not in [3,7,11,15,19,23]])
worst = []
for n in writers:
    w = load_original(n).numpy().astype(np.float64)
    L = int(n.split('.layers.')[1].split('.')[0])
    worst.append((L, 'mlp' if 'mlp' in n else ('attn' if 'self_attn' in n else 'lin'), np.linalg.norm(w.T @ d2)))
mlp_med = np.median([v for _,t_,v in worst if t_=='mlp'])
print('median mlp', round(mlp_med,3))
for L,t_,v in worst:
    if v < 0.75*mlp_med and t_=='mlp': print('LOW MLP', L, round(v,3))
attn_vals = {L: round(v,3) for L,t_,v in worst if t_=='attn'}
print('attn', attn_vals)
lin_vals = {L: round(v,3) for L,t_,v in worst if t_=='lin'}
print('lin min', min(lin_vals.values()))
